import { Component, Element, Event, EventEmitter, Host, Prop, State, Watch, h } from '@stencil/core';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';

@Component({
  tag: 'groupui-loading',
  styleUrl: 'loading.scss',
  shadow: true,
})
export class Loading {
  /**
   * activates an inverted presentation
   */
  @Prop({ reflect: true }) readonly inverted: boolean = false;

  /**
   * the size of the inlined loading spinner
   */
  @Prop({ reflect: true }) readonly size: 's' | 'm' | 'l' | 'xl' | 'xxl' | '3xl' = 'm';

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  /**
   * toggle embedded mode for use inside other components
   */
  @Prop({ reflect: true }) readonly embedded: boolean;

  /**
   * disables the background color
   */
  @Prop({ reflect: true }) readonly noTrack: boolean = false;

  @Element() host: HTMLElement;

  @State() private ariaAttributes: AriaAttributes;

  componentWillLoad() {
    this.updateSize();
    this.updateStrokeWidth();
    this.ariaAttributes = extractAriaAttributes(this.host);
  }

  componentDidLoad() {
    this.groupuiDidLoad.emit();
  }

  @Watch('size')
  onSizeChanged() {
    this.updateSize();
    this.updateStrokeWidth();
  }

  private updateSize() {
    let circleDiameter: string;
    let padding: string;
    switch (this.size) {
      case 's':
        padding = '1px';
        circleDiameter = `calc(var(--groupui-sys-spacing-400) - calc(2 * ${padding}))`;
        break;
      case 'l':
        padding = '3px';
        circleDiameter = `calc(var(--groupui-sys-spacing-800) - calc(2 * ${padding}))`;
        break;
      case 'xl':
        padding = '4px';
        circleDiameter = `calc(var(--groupui-sys-spacing-1200) - calc(2 * ${padding}))`;
        break;
      case 'xxl':
        padding = '4px';
        circleDiameter = `calc(var(--groupui-sys-spacing-2400) - calc(2 * ${padding}))`;
        break;
      case '3xl':
        padding = '4px';
        circleDiameter = `calc(var(--groupui-sys-spacing-3400) - calc(2 * ${padding}))`;
        break;
      case 'm':
      default:
        padding = '2px';
        circleDiameter = `calc(var(--groupui-sys-spacing-600) - calc(2 * ${padding}))`;
        break;
    }
    this.host.style.setProperty('--circle-diameter', circleDiameter);
    this.host.style.setProperty('--padding', padding);
  }

  private updateStrokeWidth() {
    let strokeWidthToken;
    switch (this.size) {
      case 'xxl':
        strokeWidthToken = 'var(--groupui-sys-border-width-xl)';
        break;
      case '3xl':
        strokeWidthToken = 'var(--groupui-sys-border-width-xxxl)';
        break;
      case 's':
      case 'm':
      case 'l':
      case 'xl':
      default:
        strokeWidthToken = 'var(--groupui-sys-border-width-m)';
        break;
    }
    this.host.style.setProperty('--circle-stroke-width', strokeWidthToken);
  }

  render() {
    return (
      <Host>
        <svg
          id="loading"
          role="status"
          aria-live="polite"
          aria-label="loading"
          aria-busy="true"
          {...this.ariaAttributes}
        >
          <circle id="circle-track" />
          <circle id="circle-fill" />
        </svg>
      </Host>
    );
  }
}
